from java.util import Date

def copyProperties(node):
	# perspective arrays and python lists (but not strings)
	if 'PropertyTreeScriptWrapper$ArrayWrapper' in str(type(node)) or \
	(isinstance(node, collections.Sequence) and not isinstance(node, basestring)):
		nodeCopy = []
		for i in node:
			nodeCopy.append(copyProperties(i))
		return nodeCopy
	# perspective objects and python dictionaries
	elif 'PropertyTreeScriptWrapper$ObjectWrapper' in str(type(node)) or isinstance(node, collections.Mapping):
		nodeCopy = {}
		for k in node:
			nodeCopy[k] = copyProperties(node[k])
		return nodeCopy
	# single value, with optional date conversion
	else:
