# creates a new copy of the given property tree, replacing Instant formatted strings with java.util.Date
import collections

def convertProperties(node):
	# perspective arrays and python lists (but not strings)
	if 'PropertyTreeScriptWrapper$ArrayWrapper' in str(type(node)) or \
	(isinstance(node, collections.Sequence) and not isinstance(node, basestring)):
		nodeCopy = []
		for i in node:
			nodeCopy.append(convertProperties(i))
		return nodeCopy
	# perspective objects and python dictionaries
	elif 'PropertyTreeScriptWrapper$ObjectWrapper' in str(type(node)) or isinstance(node, collections.Mapping):
		nodeCopy = {}
		for k in node:
			nodeCopy[k] = convertProperties(node[k])
		return nodeCopy
	# single value
	else:
		# this will attempt to convert the string back into Date, otherwise just returns the value
		if isinstance(node, basestring):
			try:
				return self.view.rootContainer.dateFromInstant(node)
			except:
				return node
		return node

return convertProperties(propertyTree)

